INSERT INTO `courses` (`id`, `title`, `slug`, `tagline`, `description`, `thumbnail`, `trailer_url`, `instructor_id`, `category`, `level`, `language`, `price`, `discount_percent`, `student_discount`, `is_free`, `is_featured`, `is_published`, `rating`, `total_students`, `total_reviews`, `duration_mins`, `start_date`, `created_at`, `updated_at`, `installments_enabled`, `installments_count`, `installment_count`, `discount_end_date`) VALUES
(8, 'Digital Marketing', '-igital-arketing', '', '<h3><strong>Course Overview</strong></h3><p>Join our <strong>Digital Marketing Course in Pakistan</strong> and learn the skills that actually make money. Whether you want to start freelancing, grow your business, or build a career — this course is designed to get you real results, not just theory.</p><p><br></p><h2><strong>Course Details</strong></h2><ul><li><strong>Schedule:</strong> Friday, Saturday, Sunday</li><li><strong>Time:</strong> 7:00 PM – 8:00 PM</li><li><strong>Duration:</strong> 1 hour per class (3 days/week)</li><li><strong>Mode:</strong> Dual Mode (Onsite or Live Online)</li><li><strong>Course Fee:</strong> Rs. 25,000</li><li><strong>Limited Time Offer:</strong> <strong>50% OFF → Rs. 18,750</strong></li><li><strong>Installments:</strong> Available</li></ul><h2><strong>What You Will Learn</strong></h2><p>A complete, practical <strong>digital marketing training program</strong>:</p><h3><strong>1. Search Engine Optimization (SEO)</strong></h3><ul><li>Keyword research &amp; competitor analysis</li><li>On-page SEO (content, structure, meta tags)</li><li>Technical SEO fundamentals</li><li>Off-page SEO &amp; backlink strategies</li></ul><h3><strong>2. Social Media Marketing (SMM)</strong></h3><ul><li>Facebook &amp; Instagram growth strategies</li><li>Content planning &amp; audience targeting</li><li>Page setup and optimization</li></ul><h3><strong>3. Paid Advertising (Meta &amp; Google Ads)</strong></h3><ul><li>Facebook &amp; Instagram Ads (Meta Ads Manager)</li><li>Campaign setup, targeting &amp; budgeting</li><li>Ad creatives, copywriting &amp; optimization</li></ul><h3><strong>4. Content Marketing &amp; Branding</strong></h3><ul><li>Brand identity &amp; positioning</li><li>Content strategy for engagement</li><li>Visual &amp; written content planning</li></ul><h3><strong>5. Lead Generation &amp; Sales Funnels</strong></h3><ul><li>Funnel creation strategies</li><li>Landing page basics</li><li>Converting traffic into customers</li></ul><h3><strong>6. Freelancing &amp; Online Earning</strong></h3><ul><li>Fiverr &amp; Upwork complete setup</li><li>Gig ranking strategies</li><li>Client handling &amp; deal closing</li></ul><h2><strong>Why Choose This Course</strong></h2><ul><li><strong>Dual Mode Flexibility</strong> — Learn onsite or online</li><li><strong>Practical Training</strong> — Work on real campaigns &amp; projects</li><li><strong>Step-by-Step Learning</strong> — From beginner to advanced</li><li><strong>Career-Focused Skills</strong> — Start earning or scale your business</li></ul><h2><strong>Exclusive Bonuses</strong></h2><ul><li><strong>1 Year Free Mentorship</strong> (guidance even after course completion)</li><li><strong>50% Discount (Limited Time Offer)</strong></li><li><strong>Installment Plan Available</strong></li><li><strong>Hands-on Projects &amp; Real Campaign Experience</strong></li></ul><h2><strong>Enroll Now</strong></h2><p>Limited seats available.</p><p> Start your digital marketing journey today and build real income skills.</p>', 'https://www.inseec.com/wp-content/uploads/sites/32/2025/11/guide-inseec-hero-quest-ce-que-Marketing-Digital.jpg?w=1372', NULL, NULL, 'Marketing', 'Beginner', 'English', 25000.00, 25, 10, 0, 1, 0, 0.00, 14, 0, 2880, '2026-05-01', '2026-04-06 17:40:36', '2026-05-23 03:48:56', 1, 0, 2, '2026-04-12'),
(12, 'Programming fundamentals and Python', '-rogramming-fundamentals-and-ython', '', '<h1><strong>omplete Programming Course (32 Days + 15 Days AI Bonus)</strong></h1><p>A structured, beginner-to-advanced roadmap designed to take you from zero to building real applications.</p><p><br></p><h2><strong>Module 1 : Programming Foundations (Days 1–5)</strong></h2><p>Build core understanding of how programming actually works.</p><p><strong>Day 1: Introduction to Programming</strong></p><ul><li>What is programming</li><li>CPU cycle &amp; execution</li><li>Binary basics</li><li>Memory fundamentals</li><li>Programming languages overview</li></ul><p><strong>Day 2: Problem Solving Fundamentals</strong></p><ul><li>Algorithms</li><li>Flowcharts</li><li>Pseudocode</li><li>Logical thinking techniques</li></ul><p><strong>Day 3: Development Environment Setup</strong></p><ul><li>VS Code setup</li><li>Compiler basics</li><li>Python installation &amp; setup</li></ul><p><strong>Day 4: Variables &amp; Memory</strong></p><ul><li>Data types</li><li>Memory concepts (stack basics)</li><li>Naming conventions</li></ul><p><strong>Day 5: Operators</strong></p><ul><li>Arithmetic operators</li><li>Logical operators</li><li>Bitwise operations</li></ul><h2><strong>Module 2 : Core Programming with C++ (Days 6–14)</strong></h2><p>Master logic building and low-level understanding.</p><p><strong>Day 6: C++ Basics &amp; I/O</strong></p><ul><li>Program structure</li><li>Input/Output (cin/cout)</li><li>Compilation process</li></ul><p><strong>Day 7: Control Flow</strong></p><ul><li>if / else</li><li>switch statements</li></ul><p><strong>Day 8: Loops</strong></p><ul><li>for loop</li><li>while loop</li><li>Nested loops</li></ul><p><strong>Day 9: Functions</strong></p><ul><li>Function structure</li><li>Scope</li><li>Recursion</li></ul><p><strong>Day 10: Arrays &amp; Strings</strong></p><ul><li>1D &amp; 2D arrays</li><li>String handling</li></ul><p><strong>Day 11: Pointers</strong></p><ul><li>Memory concepts</li><li>References</li></ul><p><strong>Day 12: Structs &amp; OOP Intro</strong></p><ul><li>Structs</li><li>Introduction to OOP</li></ul><p><strong>Day 13: File Handling</strong></p><ul><li>Reading &amp; writing files</li></ul><p><strong>Day 14: Capstone Project</strong></p><ul><li>Build a Student Management System</li></ul><h2><strong>Module 3 : Python Development (Days 15–22)</strong></h2><p>Transition into modern, high-demand programming.</p><p><strong>Day 15: Python Introduction</strong></p><ul><li>Setup</li><li>REPL</li></ul><p><strong>Day 16: Data Types</strong></p><ul><li>Lists</li><li>Dictionaries</li><li>Sets</li></ul><p><strong>Day 17: Control Flow</strong></p><ul><li>Loops</li><li>List comprehensions</li></ul><p><strong>Day 18: Functions</strong></p><ul><li>Arguments</li><li>*args &amp; **kwargs</li></ul><p><strong>Day 19: Strings</strong></p><ul><li>Formatting</li><li>Regex basics</li></ul><p><strong>Day 20: Modules &amp; Packages</strong></p><ul><li>pip</li><li>Working with packages</li></ul><p><strong>Day 21: File Handling</strong></p><ul><li>CSV</li><li>JSON</li></ul><p><strong>Day 22: Debugging &amp; Error Handling</strong></p><ul><li>Exceptions</li><li>Logging</li></ul><h2><strong>Module 4 : Advanced Python &amp; Real-World Skills (Days 23–32)</strong></h2><p>Learn industry-level concepts and build production-ready skills.</p><p><strong>Day 23: Object-Oriented Programming</strong></p><ul><li>Classes</li><li>Inheritance</li></ul><p><strong>Day 24: Generators &amp; Iterators</strong></p><ul><li>yield</li><li>Iteration patterns</li></ul><p><strong>Day 25: Decorators &amp; Closures</strong></p><p><strong>Day 26: Functional Programming</strong></p><ul><li>map / filter</li></ul><p><strong>Day 27: Concurrency</strong></p><ul><li>Threading</li><li>Async programming</li></ul><p><strong>Day 28: Data Analysis</strong></p><ul><li>pandas</li><li>numpy</li></ul><p><strong>Day 29: Data Visualization</strong></p><ul><li>matplotlib</li><li>seaborn</li></ul><p><strong>Day 30: APIs &amp; Integration</strong></p><ul><li>requests</li><li>JSON handling</li></ul><p><strong>Day 31: Testing &amp; Best Practices</strong></p><ul><li>pytest</li><li>TDD basics</li></ul><p><strong>Day 32: Final Project</strong></p><ul><li>Build a complete real-world application</li></ul><h2><strong>🎁 Bonus: 15 Days AI Specialization</strong></h2><p>Get ahead with practical AI skills:</p><ul><li>Introduction to AI &amp; Machine Learning</li><li>Using AI tools for developers</li><li>Prompt engineering (ChatGPT, AI workflows)</li><li>Automating tasks with AI</li><li>AI for freelancing &amp; productivity</li><li>Real-world AI mini projects&nbsp;</li></ul><p><br></p>', 'https://images.stockcake.com/public/e/e/6/ee6071b7-ef42-45e4-ba8c-9fc44bbdfa22_large/coding-at-night-stockcake.jpg', NULL, 41, 'Programming', 'Beginner', 'English', 100000.00, 0, 10, 0, 0, 0, 0.00, 1, 0, 2880, '2026-05-01', '2026-04-21 15:28:10', '2026-06-01 01:09:47', 1, 0, 2, '2026-04-21'),
(13, 'Programming Fundamentals, Python Mastery and Ai Development', '-rogramming-undamentals-ython-astery-and-i-evelopment', 'Master Python and Clear Programming fundamental', '<h1><br></h1><p>A structured, beginner-to-advanced roadmap designed to take you from zero to building real applications.</p><p><br></p><h2><strong>Module 1 : Programming Foundations (Days 1–5)</strong></h2><p>Build core understanding of how programming actually works.</p><p><strong>Day 1: Introduction to Programming</strong></p><ul><li>What is programming</li><li>CPU cycle &amp; execution</li><li>Binary basics</li><li>Memory fundamentals</li><li>Programming languages overview</li></ul><p><strong>Day 2: Problem Solving Fundamentals</strong></p><ul><li>Algorithms</li><li>Flowcharts</li><li>Pseudocode</li><li>Logical thinking techniques</li></ul><p><strong>Day 3: Development Environment Setup</strong></p><ul><li>VS Code setup</li><li>Compiler basics</li><li>Python installation &amp; setup</li></ul><p><strong>Day 4: Variables &amp; Memory</strong></p><ul><li>Data types</li><li>Memory concepts (stack basics)</li><li>Naming conventions</li></ul><p><strong>Day 5: Operators</strong></p><ul><li>Arithmetic operators</li><li>Logical operators</li><li>Bitwise operations</li></ul><h2><strong>Module 2 : Core Programming with C++ (Days 6–14)</strong></h2><p>Master logic building and low-level understanding.</p><p><strong>Day 6: C++ Basics &amp; I/O</strong></p><ul><li>Program structure</li><li>Input/Output (cin/cout)</li><li>Compilation process</li></ul><p><strong>Day 7: Control Flow</strong></p><ul><li>if / else</li><li>switch statements</li></ul><p><strong>Day 8: Loops</strong></p><ul><li>for loop</li><li>while loop</li><li>Nested loops</li></ul><p><strong>Day 9: Functions</strong></p><ul><li>Function structure</li><li>Scope</li><li>Recursion</li></ul><p><strong>Day 10: Arrays &amp; Strings</strong></p><ul><li>1D &amp; 2D arrays</li><li>String handling</li></ul><p><strong>Day 11: Pointers</strong></p><ul><li>Memory concepts</li><li>References</li></ul><p><strong>Day 12: Structs &amp; OOP Intro</strong></p><ul><li>Structs</li><li>Introduction to OOP</li></ul><p><strong>Day 13: File Handling</strong></p><ul><li>Reading &amp; writing files</li></ul><p><strong>Day 14: Capstone Project</strong></p><ul><li>Build a Student Management System</li></ul><h2><strong>Module 3 : Python Development (Days 15–22)</strong></h2><p>Transition into modern, high-demand programming.</p><p><strong>Day 15: Python Introduction</strong></p><ul><li>Setup</li><li>REPL</li></ul><p><strong>Day 16: Data Types</strong></p><ul><li>Lists</li><li>Dictionaries</li><li>Sets</li></ul><p><strong>Day 17: Control Flow</strong></p><ul><li>Loops</li><li>List comprehensions</li></ul><p><strong>Day 18: Functions</strong></p><ul><li>Arguments</li><li>*args &amp; **kwargs</li></ul><p><strong>Day 19: Strings</strong></p><ul><li>Formatting</li><li>Regex basics</li></ul><p><strong>Day 20: Modules &amp; Packages</strong></p><ul><li>pip</li><li>Working with packages</li></ul><p><strong>Day 21: File Handling</strong></p><ul><li>CSV</li><li>JSON</li></ul><p><strong>Day 22: Debugging &amp; Error Handling</strong></p><ul><li>Exceptions</li><li>Logging</li></ul><h2><strong>Module 4 : Advanced Python &amp; Real-World Skills (Days 23–32)</strong></h2><p>Learn industry-level concepts and build production-ready skills.</p><p><strong>Day 23: Object-Oriented Programming</strong></p><ul><li>Classes</li><li>Inheritance</li></ul><p><strong>Day 24: Generators &amp; Iterators</strong></p><ul><li>yield</li><li>Iteration patterns</li></ul><p><strong>Day 25: Decorators &amp; Closures</strong></p><p><strong>Day 26: Functional Programming</strong></p><ul><li>map / filter</li></ul><p><strong>Day 27: Concurrency</strong></p><ul><li>Threading</li><li>Async programming</li></ul><p><strong>Day 28: Data Analysis</strong></p><ul><li>pandas</li><li>numpy</li></ul><p><strong>Day 29: Data Visualization</strong></p><ul><li>matplotlib</li><li>seaborn</li></ul><p><strong>Day 30: APIs &amp; Integration</strong></p><ul><li>requests</li><li>JSON handling</li></ul><p><strong>Day 31: Testing &amp; Best Practices</strong></p><ul><li>pytest</li><li>TDD basics</li></ul><p><strong>Day 32: Final Project</strong></p><ul><li>Build a complete real-world application</li></ul><h2><strong>🎁 Bonus: 15 Days AI Specialization</strong></h2><p>Get ahead with practical AI skills:</p><ul><li>Introduction to AI &amp; Machine Learning</li><li>Using AI tools for developers</li><li>Prompt engineering (ChatGPT, AI workflows)</li><li>Automating tasks with AI</li><li>AI for freelancing &amp; productivity</li><li>Real-world AI mini projects&nbsp;</li></ul><p><br></p>', 'https://www.udacity.com/blog/wp-content/uploads/2020/12/Python-Tutorial_Blog-scaled.jpeg', NULL, 44, 'Programming', 'Intermediate', 'English', 75000.00, 0, 10, 0, 1, 0, 0.00, 50, 0, 3780, '2026-05-15', '2026-05-06 23:11:10', '2026-06-16 12:24:48', 0, 0, 1, NULL),
(14, 'Applied Artificial Intelligence - Level 4', '-pplied-rtificial-ntelligence-evel-4', 'Practical AI Training for a Smarter Tomorrow', '<h1><strong>Government Certified Training Program</strong></h1><p>Step into the future with the <strong>Applied Artificial Intelligence (AI) Course</strong>, a comprehensive industry-focused training program designed to equip students with practical AI skills, productivity tools, automation techniques, and modern workplace competencies. This course is ideal for students, freelancers, professionals, and job seekers who want to build a career in the rapidly growing field of Artificial Intelligence.</p><p>Offered under government-supported skill development initiatives, this training program aligns with the vision of the <strong>Punjab Government</strong>, <strong>Punjab Vocational Training Council (PVTC)</strong>, and <strong>National Vocational &amp; Technical Training Commission (NAVTTC)</strong> to prepare youth for emerging digital careers and future workforce demands.</p><h2><strong>Course Highlights</strong></h2><h3><strong>Portfolio-Based Learning</strong></h3><p>Students work on real-world AI projects throughout the course, enabling them to develop a professional portfolio that showcases their practical skills and enhances employability.</p><h3><strong>Freelancing Opportunities</strong></h3><p>Learn how Artificial Intelligence tools can be used for freelancing, digital services, content creation, research, automation, and business productivity, opening doors to local and international earning opportunities.</p><h3><strong>AI Skill Development</strong></h3><p>Gain hands-on experience with modern AI technologies, prompt engineering, AI-powered productivity tools, generative AI platforms, machine learning concepts, and intelligent automation systems.</p><h3><strong>Productivity &amp; Automation Skills</strong></h3><p>Discover how AI can automate repetitive tasks, improve efficiency, streamline workflows, and increase productivity in both personal and professional environments.</p><h3><strong>Modern Workplace Readiness</strong></h3><p>Develop the digital competencies required in today\'s technology-driven workplaces, including AI-assisted communication, data handling, research, content generation, and business process optimization.</p><h3><strong>Industry-Oriented Training</strong></h3><p>The curriculum is designed according to current industry trends, ensuring learners acquire practical and market-relevant skills demanded by employers and businesses.</p><h3><strong>Government Certification</strong></h3><p>Upon successful completion, students receive a recognized certification that validates their skills and supports career advancement opportunities.</p><h2><strong>Course Duration</strong></h2><p><strong>6 Months Comprehensive Training Program</strong></p><h2><strong>Who Should Enroll?</strong></h2><ul><li>Students seeking future-ready technology skills</li><li>Fresh graduates looking to improve employability</li><li>Freelancers aiming to expand service offerings</li><li>Professionals interested in AI adoption</li><li>Entrepreneurs seeking business automation solutions</li><li>Individuals preparing for digital careers</li></ul><h2><strong>Why Choose This AI Course?</strong></h2><p>Artificial Intelligence is transforming industries worldwide. From business automation and content creation to customer support, marketing, education, and software development, AI is becoming an essential skill across every sector. This course provides practical training that bridges the gap between theoretical concepts and real-world implementation.</p><p>Through hands-on exercises, project-based learning, and practical applications, participants gain the confidence to utilize AI tools effectively in professional environments and freelance marketplaces.</p><h2><strong>Government-Supported Skill Development Initiative</strong></h2><p>This training program supports the mission of the <strong>Government of Punjab</strong>, <strong>Punjab Vocational Training Council (PVTC)</strong>, and <strong>NAVTTC</strong> to empower youth with modern technological skills and improve employment opportunities through quality vocational and technical education.</p><p>Interested candidates can explore available training opportunities through official <strong>NAVTTC course registration</strong> channels and government-supported skill development programs.</p><h2><strong>Keywords</strong></h2><p>Punjab Government Course, Government Course, Free Courses, NAVTTC Course Registration, NAVTTC Courses, Applied AI Course, AI Courses, Artificial Intelligence Training, Government Certified Course, Punjab Vocational Training Council, PVTC Courses, Digital Skills Training, AI Certification Program, Free Government Courses Pakistan, Technical Training Program, Freelancing Course, Skill Development Program, Future Skills Training.</p>', 'https://graphicafix.com/images/pvtc_course_thumbnail.jpg', NULL, NULL, 'Artificial Intelligence', 'Advanced', 'English', 0.00, 0, 10, 1, 0, 0, 0.00, 47, 0, 0, '2026-07-01', '2026-06-16 12:56:18', '2026-06-28 11:04:45', 0, 0, 1, NULL),
