INSERT INTO `letters` (`id`, `title`, `letter_type`, `recipient_name`, `recipient_company`, `recipient_email`, `recipient_address`, `subject`, `body_html`, `footer_note`, `status`, `created_by`, `created_at`, `updated_at`) VALUES
(3, 'Revised subscripton Payment', 'custom', 'Hafiz Arsalan', 'Qaswa Elevators', 'qaswaelevators@gmail.com', 'Gulshan-e-Shamal, Adyala road, rawalpindi', 'Revised subscripton Payment', '<p>Dear Hafiz Arsalan ,</p><p>Please note that the Social Media Management subscription fee has been revised from 45,000 to 55,000, effective from next month. The updated price will apply to the May payment cycle.</p><p>Please also note that social media campaigns will be charged separately and are not included in this subscription.</p><p><br></p><p>Thank you for your continued trust.</p><p><br></p><p><strong>Best regards,</strong></p><p><strong>Ibadullah Shalmany</strong></p><p><strong>Graphica Fix</strong></p>', '', 'draft', 25, '2026-04-18 13:25:04', '2026-04-18 13:35:16'),
(4, 'ALgo platform description', 'custom', '', '', '', '', '', '<h1><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">The Ultimate Trading Community &amp; Algorithm Management Platform</strong></h1><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This platform is a comprehensive, turnkey SaaS solution designed specifically for trading educators, signal providers, and financial influencers. It replaces the need for multiple expensive software subscriptions (like Kajabi, LaunchPass, or Whop) by providing an all-in-one ecosystem to monetize audiences, automate access, and deliver educational content.</span></p><h2><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Core Features &amp; Capabilities</strong></h2><h3><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">1. Zero-Touch TradingView Automation</strong></h3><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Say goodbye to manually managing TradingView invite-only scripts. The platform features a fully automated access pipeline.</span></p><ul><li><strong style=\"background-color: transparent;\">Instant Provisioning:</strong><span style=\"background-color: transparent;\"> When a user\'s payment clears, the system automatically grants their TradingView username access to your premium indicators.</span></li><li><strong style=\"background-color: transparent;\">Auto-Revoke:</strong><span style=\"background-color: transparent;\"> If a subscription expires, fails to renew, or is canceled, the platform instantly communicates with TradingView to revoke script access, protecting your intellectual property without any manual intervention.</span></li></ul><h3><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">2. Seamless Community &amp; Subscription Management</strong></h3><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Monetize your expertise with automated paywalls for your premium communities.</span></p><ul><li><strong style=\"background-color: transparent;\">Telegram Automation:</strong><span style=\"background-color: transparent;\"> Integrated bots automatically invite paying members to VIP Telegram channels and instantly kick members whose subscriptions lapse.</span></li><li><strong style=\"background-color: transparent;\">Tiered Memberships:</strong><span style=\"background-color: transparent;\"> Create multiple subscription levels (e.g., Basic, VIP, Lifetime) with varying levels of access to signals, chats, and indicators.</span></li></ul><h3><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">3. Integrated Learning Management System (LMS)</strong></h3><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Transform your platform into a fully-fledged trading academy.</span></p><ul><li><strong style=\"background-color: transparent;\">Paid &amp; Free Courses:</strong><span style=\"background-color: transparent;\"> Host video lessons, quizzes, and resources. Gate premium courses behind specific subscription tiers or sell them as one-off purchases.</span></li><li><strong style=\"background-color: transparent;\">Content Marketing Hub (Blogs):</strong><span style=\"background-color: transparent;\"> A built-in CMS allows you to publish both public-facing SEO articles to drive traffic, and private, premium market-breakdown blogs exclusively for paying members.</span></li></ul><h3><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">4. Frictionless Global &amp; Local Payments</strong></h3><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Never lose a sale due to payment barriers. The platform is integrated with flexible payment gateways to capture both global and local audiences:</span></p><ul><li><strong style=\"background-color: transparent;\">Global Gateways:</strong><span style=\"background-color: transparent;\"> Credit/Debit Card processing and Crypto payments.</span></li><li><strong style=\"background-color: transparent;\">Local Gateways:</strong><span style=\"background-color: transparent;\"> Native integration with Easypaisa and Jazzcash, perfectly optimized for the Pakistani and regional markets.</span></li></ul><h3><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">5. Automated Email Center</strong></h3><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Keep your community engaged and reduce churn with built-in email automation. The system triggers instant emails for payment confirmations, password resets, failed billing alerts, and welcome onboarding sequences.</span></p><h2><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">The Command Center: Admin Dashboard</strong></h2><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">The backend is a powerhouse designed to give the business owner total control over their data, users, and revenue.</span></p><ul><li><strong style=\"background-color: transparent;\">Overview:</strong><span style=\"background-color: transparent;\"> A real-time executive snapshot of active subscriptions, recent revenue, and daily platform traffic.</span></li><li><strong style=\"background-color: transparent;\">Automation:</strong><span style=\"background-color: transparent;\"> The rules engine where you configure automated triggers (e.g., actions upon payment failure or trial expiration).</span></li><li><strong style=\"background-color: transparent;\">Telegram:</strong><span style=\"background-color: transparent;\"> Manage your bot connections, channel links, and API integrations.</span></li><li><strong style=\"background-color: transparent;\">Checks:</strong><span style=\"background-color: transparent;\"> An audit log for troubleshooting payment webhook statuses and TradingView API delivery confirmations.</span></li><li><strong style=\"background-color: transparent;\">User Monitor:</strong><span style=\"background-color: transparent;\"> Live tracking of user activity, logins, and engagement across the platform.</span></li><li><strong style=\"background-color: transparent;\">User Manager:</strong><span style=\"background-color: transparent;\"> A complete CRM to manually edit user profiles, adjust subscription dates, or grant manual overrides.</span></li><li><strong style=\"background-color: transparent;\">Affiliates:</strong><span style=\"background-color: transparent;\"> A built-in referral system allowing your members to earn commissions for bringing in new subscribers, turning your audience into a marketing team.</span></li><li><strong style=\"background-color: transparent;\">Plan Manager:</strong><span style=\"background-color: transparent;\"> Create, edit, and delete subscription tiers, trial periods, and pricing models on the fly.</span></li><li><strong style=\"background-color: transparent;\">Courses:</strong><span style=\"background-color: transparent;\"> Upload videos, organize modules, and manage student access for your educational content.</span></li><li><strong style=\"background-color: transparent;\">Blog Manager:</strong><span style=\"background-color: transparent;\"> Write, draft, and publish articles, managing SEO metadata and premium access locks.</span></li><li><strong style=\"background-color: transparent;\">Email Center:</strong><span style=\"background-color: transparent;\"> Broadcast mass announcements to your users or configure automated transactional email templates.</span></li><li><strong style=\"background-color: transparent;\">Analytics:</strong><span style=\"background-color: transparent;\"> Deep dive into financial metrics, churn rates, MRR (Monthly Recurring Revenue), and user retention graphs.</span></li><li><strong style=\"background-color: transparent;\">System:</strong><span style=\"background-color: transparent;\"> Global platform settings, API keys, branding customization, and security protocols.</span></li></ul><h2><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">The Client/Member Portal</strong></h2><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Your users get a beautifully designed, intuitive dashboard that makes managing their subscription effortless. From the Client Portal, users can:</span></p><ul><li><span style=\"background-color: transparent;\">Connect their TradingView username and Telegram account.</span></li><li><span style=\"background-color: transparent;\">Upgrade, downgrade, or cancel their subscription plans.</span></li><li><span style=\"background-color: transparent;\">Update their payment methods (Cards, Crypto, Easypaisa/Jazzcash).</span></li><li><span style=\"background-color: transparent;\">Access gated courses, premium blogs, and exclusive video content.</span></li><li><span style=\"background-color: transparent;\">Grab their unique affiliate link to refer friends.</span></li></ul><h2><br></h2><h2><strong>Technical Architecture &amp; Infrastructure (The Tech Stack)</strong></h2><p>The platform is built on a modern, enterprise-grade technology stack designed for high concurrency, ensuring that the system remains lightning-fast even when thousands of users are accessing courses, processing payments, or receiving signals simultaneously.</p><h3>1. Frontend (User Interface &amp; Experience)</h3><ul><li><strong>Framework:</strong> Built with <strong>React.js / Next.js</strong> (or Vue.js/Blade if using Laravel Livewire/Inertia), providing a blazing-fast, single-page application (SPA) experience with zero page-reload lag.</li><li><strong>Styling:</strong> <strong>Tailwind CSS</strong> ensures a highly responsive, mobile-first design that looks flawless on any device, alongside dynamic CSS variables for instant, seamless white-label color swapping.</li></ul><h3><strong>2. Backend (Server &amp; Core Logic)</strong></h3><ul><li><strong>Core Environment:</strong> Powered by <strong>PHP 8.x and the Laravel Framework</strong>, the industry standard for secure, scalable SaaS applications. Its MVC (Model-View-Controller) architecture ensures clean, maintainable, and highly efficient code.</li><li><strong>Asynchronous Automation (Queues):</strong> Utilizing Laravel\'s robust queue system (and Laravel Horizon), background tasks—such as sending automated emails, verifying crypto payment confirmations, and triggering Telegram bot kicks—are processed asynchronously. This guarantees that the main user dashboard remains lightning-fast, no matter how heavy the server load gets.</li></ul><h3><strong>&nbsp;3. Third-Party API Integrations</strong></h3><ul><li><strong>TradingView Webhooks:</strong> Secure, bi-directional REST API communication for instant invite-only script provisioning and revocation.</li><li><strong>Telegram Bot API:</strong> Seamless integration with Telegram\'s API for automated VIP group management and instant channel kicks/invites.</li><li><strong>Payment Gateways:</strong> Direct API integrations with global processors (Cards/Crypto) and local Pakistani gateways (Easypaisa/JazzCash) for instant callback verification.</li></ul><h3><strong>4. Database &amp; Data Integrity</strong></h3><ul><li>Relational Database: The platform is powered by a highly optimized MySQL database architecture. Paired with Laravel’s Eloquent ORM, it ensures lightning-fast read/write speeds and absolute data integrity for user profiles, financial transactions, and complex subscription logs.</li><li>Query Optimization: Advanced MySQL indexing, structured relational tables, and eager loading guarantee that heavy admin tasks—like MRR calculations, affiliate tracking, and live user monitoring—render in milliseconds without bottlenecking the system under high traffic.</li><li>Reliability: MySQL is the world\'s most popular open-source database, chosen for its proven stability and ACID-compliant transaction handling, ensuring that every payment and subscription update is recorded flawlessly.</li></ul><h3><strong>5. Security &amp; Uptime</strong></h3><ul><li><strong>Enterprise Security:</strong> Laravel provides native, bank-level protection against common vulnerabilities, including built-in CSRF (Cross-Site Request Forgery) protection, XSS (Cross-Site Scripting) prevention, and secure SQL injection shielding.</li><li><strong>Authentication:</strong> Secure session management and encrypted password hashing (Bcrypt/Argon2) prevent unauthorized access and account sharing.</li><li><strong>Hosting &amp; Delivery:</strong> Cloud-native infrastructure deployed behind a CDN (Content Delivery Network) to ensure 99.9% uptime, global low-latency access, and automated DDoS protection.</li></ul>', '', 'draft', 25, '2026-04-28 12:28:08', '2026-04-28 12:48:35'),
(5, 'student policy', 'custom', '', '', '', '', '', '<p><br></p><h3 class=\"ql-align-center\"><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">STUDENT PRIVACY POLICY</strong></h3><p><br></p><p class=\"ql-align-center\"><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">&nbsp;</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">For Students of Graphica Fix</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">1. Purpose of Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This policy is designed to maintain a professional, respectful, and productive online learning environment for all students enrolled in courses offered by Graphica Fix.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">All students are expected to follow these rules and ethical standards throughout the course duration.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"> 2. Student Ethical Responsibilities</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Every student must maintain professionalism and ethical behavior during classes and communication.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students Must;</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Respect instructors, classmates, and staff members.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Maintain polite and professional communication.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Avoid abusive, offensive, or inappropriate language.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Follow academic honesty and avoid plagiarism.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Use learning material responsibly and ethically.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Protect the reputation and learning environment of Graphica Fix.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students Must NOT</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Harass or disrespect instructors or classmates.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Share inappropriate content during classes.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Copy or steal another student’s work.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Record or distribute class content without permission.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Misuse course materials for commercial purposes.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">3. Assignment Submission Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are responsible for completing and submitting assignments on time.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Requirements:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* All assignments must be submitted before the given deadline.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Late submissions may result in reduced marks, warnings, or rejection.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students must ensure their work is original and properly completed.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Incomplete assignments may affect course performance and certification.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"> </span><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Responsibility</strong><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are expected to manage their time professionally and maintain consistency in learning activities.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">4. Attendance &amp; Participation Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students should attend classes regularly and actively participate in learning activities.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">### Students Must:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Join classes on time.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Participate in discussions, exercises, and class activities.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Inform the instructor in advance if unable to attend.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Maintain focus and discipline during sessions.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Repeated absence without valid reason may impact course progress or certification eligibility.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 5. Instructor Instruction Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are required to follow all academic instructions provided by instructors.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">This Includes:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Following project guidelines</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Completing assigned tasks</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Respecting classroom rules</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Following technical and educational procedures</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Applying feedback and corrections professionally</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Failure to follow instructor guidance may affect student evaluation and learning outcomes.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"> 6. Communication Policy</strong></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"> Students must:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Use respectful communication in chats, calls, emails, and groups.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Keep discussions course-related and professional.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Avoid unnecessary arguments or disruptive behavior.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students must NOT:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Privately pressure instructors for special treatment.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Share personal promotions or advertisements during classes.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Disturb the learning environment of other students.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 7. Course Material Protection Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">All training material provided by Graphica Fix is protected intellectual property.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are NOT allowed to:</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Copy, resell, or distribute course material.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Share paid content publicly or with non-enrolled individuals.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Reproduce company training systems for commercial use.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Violation may result in:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Removal from the course</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Permanent suspension</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Legal or disciplinary action</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">8. Professional Growth Responsibility</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are encouraged to:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Practice consistently</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Improve communication skills</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Build professional portfolios</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Develop ethical freelancing and career habits</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Apply learning in real-world projects responsibly</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">9. Certification Eligibility</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students may receive certification upon:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Successful completion of assignments</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Professional classroom behavior</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Satisfactory attendance</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Following course policies and standards</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">10. Policy Violation &amp; Disciplinary Action</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Graphica Fix reserves the right to:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Issue warnings</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Suspend access to classes</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Remove students from the program</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Deny certification for serious misconduct or repeated violations</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">Student Declaration</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">I understand and agree to follow all policies, ethical responsibilities, classroom standards, and academic instructions established by Graphica Fix.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"> Student Information</span></p><p><br></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">_____________________________________________________________________________________</span></p><p><br></p><p class=\"ql-align-center\"><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\">FEE SUBMISSION &amp; ENROLLMENT POLICY</strong></p><p class=\"ql-align-center\"><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students of Graphica Fix;</span></p><p><br></p><p><br></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 1. Purpose of This Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This policy is designed to ensure a smooth, transparent, and fair enrollment process for all students who join the **7-Day Free Trial Program** offered by Graphica Fix.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">The goal is to help students experience real learning first and then make a confident and informed decision about continuing the course.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 2. 7-Day Free Trial Enrollment System</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">All new students are automatically enrolled in a **7-Day Free Trial Period**.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">During this period:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students receive full access to classes and learning material.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students participate in real training sessions.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students complete assignments and practice tasks.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students experience instructor guidance and course structure.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This trial is designed to let students understand the real value of the program before payment.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 3. Fee Submission Deadline Policy</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">After successfully joining the 7-Day Free Trial, the following policy applies:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">### Important Rule:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">✔ The **fee submission deadline is the 7th day of the free trial period**.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">### This means:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students must decide within 7 days whether they wish to continue.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* If they choose to continue, fee submission must be completed by Day 7.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Access beyond the trial is only granted after successful payment confirmation.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 4. Psychological Commitment &amp; Learning Value Principle</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">At Graphica Fix, we believe:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">&gt; “Real commitment begins when value is experienced, not just promised.”</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This policy is designed to help students:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Experience real skill development before payment</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Understand the seriousness of professional learning</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Build a strong mindset for career growth</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Avoid hesitation and wasted time</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Make confident, value-based decisions</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students who actively participate in the 7-day trial usually see the real transformation of their skills and mindset.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 5. Continuation &amp; Access Policy</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students who complete fee submission by Day 7 will continue full access to classes.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Students who do not complete payment will lose access after the trial period ends.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Re-enrollment may require approval from management.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 6. Responsibility of Students</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Students are expected to:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Attend all trial classes sincerely</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Complete assignments during the trial period</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Evaluate their learning experience honestly</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Make timely decisions regarding continuation</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This system is designed to reward seriousness and consistency.</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 7. Company Rights</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">Graphica Fix reserves the right to:</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Modify or update fee policies when necessary</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Deny continuation in case of misconduct or misuse</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">* Maintain fairness and structure in the learning environment</span></p><p><strong style=\"background-color: transparent; color: rgb(0, 0, 0);\"># 8. Final Statement</strong></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">This policy ensures that every student gets a **fair chance to experience real learning first**, and then make a confident decision based on actual value, not assumptions.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">We believe that serious students grow faster, perform better, and achieve long-term success.</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">### Student Declaration</span></p><p><span style=\"background-color: transparent; color: rgb(0, 0, 0);\">I understand and agree that I will complete or confirm my fee submission by the 7th day of my free trial period if I choose to continue learning with Graphica Fix.</span></p><p><br></p><p><br></p>', '', 'draft', 25, '2026-05-16 13:26:01', '2026-05-16 13:26:01'),
(6, 'Blog For  Student for Courses', 'custom', 'Ibad Ullah', 'Manager to delivery Department', '', '', 'Blog 01 title name :  \"Learn and Earn: How Graphicafix Summer Camp Turns Students into Professionals\"', '<p><br></p><h1><strong style=\"background-color: rgba(0, 0, 0, 0);\">Title: How It Works: Your Path from Learning to Earning with Graphicafix Summer Camp</strong></h1><p>Are you ready to turn your summer vacations into a career launchpad? At Graphicafix, we don’t just teach courses—we build future professionals. Our summer training programs are meticulously structured to take you from a complete beginner to a confident, industry-ready expert through a seamless, step-by-step system.</p><p>If you want to master high-income skills while enjoying your summer, here is exactly how our premium learning ecosystem works.</p><h3><strong style=\"background-color: rgba(0, 0, 0, 0);\">1. Live, Structured Learning Sessions</strong></h3><p>Consistency is the key to mastering any professional skill. Our training tracks run on a strict, highly professional schedule designed to keep your learning momentum at an all-time high. To maintain absolute institutional integrity, our classes are never delayed or canceled under normal circumstances. You get a predictable, reliable routine that respects your time and investment.</p><h3><strong style=\"background-color: rgba(0, 0, 0, 0);\">2. Vacation-Friendly Learning (24/7 Student Portal &amp; Recorded Access)</strong></h3><p>Want to make this summer camp fruitful without sacrificing your family holiday? We’ve got you covered. You can enjoy your summer vacations with absolutely zero fear of missing out or losing track of your classes.</p><p>Every single live session is automatically recorded and uploaded to your private, personalized <strong style=\"background-color: rgba(0, 0, 0, 0);\">Student Portal</strong>. Alongside the video recordings, you get instant access to:</p><ul><li>Comprehensive class slides</li><li>Detailed lesson transcripts</li><li>Practice files and downloadable learning materials</li></ul><p>Whether you are traveling or studying from home, your classroom travels with you.</p><h3><strong style=\"background-color: rgba(0, 0, 0, 0);\">3. The Ultimate \"Learn to Earning\" Opportunity</strong></h3><p>We believe that learning without application is a wasted opportunity. This summer camp is designed to bridge the gap between education and income.</p><p>Through our exclusive <strong style=\"background-color: rgba(0, 0, 0, 0);\">Learning to Earning initiative</strong>, top-performing and capable students won’t just graduate with a certificate—they will earn the exclusive opportunity to join the official Graphicafix professional team. You will get to work directly on <strong style=\"background-color: rgba(0, 0, 0, 0);\">Live, Real-World Client Projects</strong>, gaining invaluable agency experience and earning while you continue to grow.</p><h2><strong style=\"background-color: rgba(0, 0, 0, 0);\">Which Skill Track Will You Master This Summer?</strong></h2><p>Our specialized summer camp modules are custom-built for today’s digital and technical economy. Simply choose the path that aligns with your goals:</p><ul><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Creative UI/UX &amp; Graphic Design:</strong> Master the visuals that brands fight for.</li><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Digital Marketing &amp; Content Strategy:</strong> Learn how to drive traffic, manage platforms, and convert leads.</li><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Technical &amp; Vocational Services:</strong> Build hands-on expertise in technical troubleshooting and high-demand maintenance engineering.</li></ul><h3><strong style=\"background-color: rgba(0, 0, 0, 0);\">Ready to Transform Your Summer?</strong></h3><p>Don\'t let another summer break pass by without building an asset for your future. Secure your seat, gain access to our premium student portal, and step into a world of live project opportunities.</p><p>👉 <strong style=\"background-color: rgba(0, 0, 0, 0);\">[Click Here to Explore Our Upcoming Courses &amp; Secure Your Seat Today!]</strong></p><h3>🛠️ SEO Optimization Meta Data (For your website backend)</h3><ul><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Meta Title:</strong> How It Works | Learn &amp; Earn Summer Camp - Graphicafix</li><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Meta Description:</strong> Discover how the Graphicafix Summer Camp works. Access our digital student portal, enjoy vacation-friendly recorded classes, and get the opportunity to work on live projects!</li><li><strong style=\"background-color: rgba(0, 0, 0, 0);\">Keywords:</strong> professional skill training, digital marketing summer camp, learn and earn courses, graphic design training, vocational skills Pakistan, web development student portal.</li></ul><p><br></p>', '', 'draft', 26, '2026-05-23 04:05:02', '2026-05-23 04:05:02');
INSERT INTO `letter_templates` (`id`, `name`, `letter_type`, `body_html`, `created_at`) VALUES
(1, 'Offer Letter', 'offer_letter', '<p>Date: {{date}}</p><p><br></p><p>Dear <strong>{{recipient_name}}</strong>,</p><p><br></p><p>We are pleased to offer you the position of <strong>[Job Title]</strong> at <strong>Graphicafix</strong>, effective <strong>[Start Date]</strong>.</p><p><br></p><p>Your compensation will be <strong>Rs. [Salary]</strong> per month, subject to applicable deductions.</p><p><br></p><p>Please confirm your acceptance by signing and returning a copy of this letter by <strong>[Deadline]</strong>.</p><p><br></p><p>Sincerely,<br><strong>HR Department</strong><br>Graphicafix</p>', '2026-04-09 20:32:38'),
(2, 'Experience Letter', 'experience_letter', '<p>Date: {{date}}</p><p><br></p><p>To Whom It May Concern,</p><p><br></p><p>This is to certify that <strong>{{recipient_name}}</strong> was employed with <strong>Graphicafix</strong> as <strong>[Job Title]</strong> from <strong>[Start]</strong> to <strong>[End]</strong>.</p><p><br></p><p>During their tenure they demonstrated professionalism and dedication. We wish them well.</p><p><br></p><p>Regards,<br><strong>HR Department</strong><br>Graphicafix</p>', '2026-04-09 20:32:38'),
(3, 'No Objection Certificate', 'noc', '<p>Date: {{date}}</p><p><br></p><p>To Whom It May Concern,</p><p><br></p><p>This is to certify that <strong>{{recipient_name}}</strong>, holding the position of <strong>[Job Title]</strong>, has our full approval and no objection to <strong>[Purpose]</strong>.</p><p><br></p><p>Regards,<br><strong>Management</strong><br>Graphicafix</p>', '2026-04-09 20:32:38'),
(4, 'Warning Letter', 'warning_letter', '<p>Date: {{date}}</p><p>Confidential</p><p><br></p><p>Dear <strong>{{recipient_name}}</strong>,</p><p><br></p><p>This letter serves as a formal warning regarding <strong>[Issue]</strong> on <strong>[Date]</strong>. This behaviour violates company policy. Immediate improvement is expected.</p><p><br></p><p>Sincerely,<br><strong>HR Department</strong><br>Graphicafix</p>', '2026-04-09 20:32:38'),
(5, 'Appointment Letter', 'appointment', '<p>Date: {{date}}</p><p><br></p><p>Dear <strong>{{recipient_name}}</strong>,</p><p><br></p><p>We are delighted to appoint you as <strong>[Job Title]</strong> at Graphicafix, effective <strong>[Start Date]</strong>.</p><ul><li><strong>Salary:</strong> Rs. [Amount]/month</li><li><strong>Probation:</strong> [Duration]</li></ul><p><br></p><p>Welcome aboard!<br><strong>HR Department</strong><br>Graphicafix</p>', '2026-04-09 20:32:38');
